/**
 * look.ts — материалы предмета по ролям.
 *
 * Предмет ядра знает, из чего он сделан: у кровати это каркас, матрас, плед и
 * подушка, у полена - кора, торец и раскол. Каждая роль по умолчанию берётся
 * из набора ядра по имени, и это половина смысла каталога: «поставь здесь
 * кровать» не требует от мира ни одной строчки про материалы.
 *
 * Вторая половина - подмена. Мир отдаёт `mats` с любым подмножеством ролей и
 * получает свой материал там, где ему важно: Snowfall кладёт на кору
 * поленницы снежный налёт (`snowTint`), а проверка геометрии на Node подсовывает
 * пустые материалы, потому что наборы ядра пекутся на канве, которой у Node
 * нет. Геометрия при этом та же самая - ровно это проверке и нужно.
 */
import * as THREE from 'three';
import { type MaterialOptions } from '../materials/index.js';
/** Материалы по ролям. Роль, которой тут нет, берётся из набора ядра. */
export type Mats = Record<string, THREE.Material | undefined>;
/** Материал роли: подмена мира, иначе набор ядра `set` с настройками `o`. */
export declare function lookOf(mats: Mats | undefined, role: string, set: string, o?: MaterialOptions): THREE.Material;
/**
 * Пустые материалы на все роли сразу - для счёта геометрии без канвы. Один
 * материал на всё: проверке важны треугольники, а не карты.
 */
export declare function blankMats(): Mats;
